// Đổi link ngắn ?p=<path trong bucket> thành link XEM TRỰC TIẾP:
// - excel/word/powerpoint -> Office Viewer (xem ngay trên điện thoại, không phải tải về;
//   giới hạn của Office Viewer: file ~10MB trở xuống)
// - pdf / video / ảnh     -> mở thẳng URL Storage, trình duyệt tự render
// Path phải nằm trong bucket task-attachments (chặn '..' để không trỏ đi nơi khác).
//
// 30/07/2026: bucket task-attachments KHÔNG còn cho đọc công khai. Node "Ký link file"
// (khoá Secret nằm trong Credential, không lộ ra trình duyệt) trả signedURL hạn 1 giờ.
// Ký hụt (file đã xoá, sai path, Storage lỗi) -> rơi về FALLBACK, không trả 500.
const q = $('Webhook xem file').first().json.query || {};
const p = String(q.p || '');
const HOST = 'https://ngwkzicrnspeggunsblr.supabase.co/storage/v1';
const FALLBACK = 'https://amazing-frangollo-eb56a9.netlify.app';

let signed = '';
try { signed = String($input.first().json.signedURL || ''); } catch (e) { signed = ''; }

let target = FALLBACK;
if (p && !p.includes('..') && signed.startsWith('/object/sign/task-attachments/')) {
    const raw = HOST + signed;
    const m = p.toLowerCase().match(/\.([a-z0-9]+)$/);
    const ext = m ? m[1] : '';
    target = ['xlsx', 'xls', 'docx', 'doc', 'pptx', 'ppt'].includes(ext)
        ? 'https://view.officeapps.live.com/op/view.aspx?src=' + encodeURIComponent(raw)
        : raw;
}
return [{ json: { target } }];
